tape( 'if `α` is `0` and `β` is neither `0` nor `1`, the function returns the third input matrix scaled by `β`', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;
	var c;

	data = rarbrctatb;

	a = new Float64Array( data.A );
	b = new Float64Array( data.B );
	c = new Float64Array( data.C );

	expected = dscal( c.length, 10.0, new Float64Array( c ), 1 );

	out = dgemmsw( data.transA, data.transB, data.M, data.N, data.K, 0.0, a, data.strideA1, data.strideA2, data.offsetA, b, data.strideB1, data.strideB2, data.offsetB, 10.0, c, data.strideC1, data.strideC2, data.offsetC );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports computation over large arrays (row-major, row-major, row-major)', function test( t ) {
	var expected;
	var out;
	var N;
	var a;
	var b;
	var c;

	// Use a size which exceeds the default recursion cutoff:
	N = ( 2*defaults.CUTOFF ) + 1;

	a = ones( N*N, 'float64' );
	b = ones( a.length, 'float64' );
	c = new Float64Array( a.length );

	expected = filled( N, a.length, 'float64' );

	out = dgemmsw( 'no-transpose', 'no-transpose', N, N, N, 1.0, a, N, 1, 0, b, N, 1, 0, 1.0, c, N, 1, 0 );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports computation over large arrays (column-major, column-major, column-major)', function test( t ) {
	var expected;
	var out;
	var N;
	var a;
	var b;
	var c;

	// Use a size which exceeds the default recursion cutoff:
	N = ( 2*defaults.CUTOFF ) + 1;

	a = ones( N*N, 'float64' );
	b = ones( a.length, 'float64' );
	c = new Float64Array( a.length );

	expected = filled( N, a.length, 'float64' );

	out = dgemmsw( 'no-transpose', 'no-transpose', N, N, N, 1.0, a, 1, N, 0, b, 1, N, 0, 1.0, c, 1, N, 0 );
	t.strictEqual( out, c, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});
